                return (a_priority < b_priority);
            }
            return (strings.order(a.name, b.name) == .lt);
    }

pub fn depTypePriority(dep_type: []const u8) u8 {
            if (strings.eqlComptime(dep_type, "dependencies")) {
                return 0;
            }
            if (strings.eqlComptime(dep_type, "devDependencies")) {
                return 1;
            }
            if (strings.eqlComptime(dep_type, "peerDependencies")) {
                return 2;
            }
            if (strings.eqlComptime(dep_type, "optionalDependencies")) {
                return 3;
            }
            return 4;
    }
};

