pub fn editCatalogDefinitions(manager: *PackageManager, updates: []CatalogUpdateRequest, current_package_json: *Expr) !void {
        _ = Expr.Disabler.disable();
        defer {
        _ = Expr.Disabler.enable();
        }
        const allocator = manager.allocator;
        for (cp_iter_slice(updates)) |update| {
            _ = &update;
            if (update.catalog_name) |catalog_name| {
                _ = &catalog_name;
                _ = try updateNamedCatalog(allocator, current_package_json, catalog_name, update.package_name, update.new_version);
            } else {
                _ = try updateDefaultCatalog(allocator, current_package_json, update.package_name, update.new_version);
            }
        }
}

pub fn updateDefaultCatalog(allocator: std.mem.Allocator, package_json: *Expr, package_name: []const u8, new_version: []const u8) !void {
