                    }
                    return try std.fmt.allocPrint(allocator, "{c}={s}", .{ first_char, new_version });
                }
                if (alias) |a| {
                    _ = &a;
                    return try std.fmt.allocPrint(allocator, "npm:{s}@{c}{s}", .{ a, first_char, new_version });
                }
